de": "LIM:small_sample"}, {"rel": "auto_related_family", "node": "FAM:SF05"}]}, {"id": "FAM:SF-APPA-058", "label": "Study family SF-APPA-058: Season stability of top suppressors and negative teammate pairs", "score": 0.47, "reached_via": ["request matches RQC:RQC-051 (0.74); FAM:SF-APPA-058 auto_addresses_question RQC:RQC-051"], "attributes": {"observed_research_question": "Season stability of top suppressors and negative teammate pairs", "auto_outcome_status": "rejected", "observed_hypothesis": "Each star's top sequential suppressor is stable across seasons, and some teammate X->Y sequences have large negative premiums.", "observed_result": "2/30 (7%) stable (>=75% same top suppressor): D. Mitchell PUTBACK 75%, L. James POST_UP 75%. Negative: J. Tatum->K. Porzingis DRIVE->SPOT_UP -0.444 n=31; Giannis->Lillard DRIVE->PNR -0.263 n=31; J. Brown->J. Tatum SPOT_U [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "Only 2/30 stars meet the 75% same-top-suppressor stability rule.", "observed_sample_and_power": "30 stars x 4 seasons; min n=20/cell", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "null"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPM-052", "label": "Study family SF-APPM-052: MIA vs BOS G6 2023 agent adaptation review", "score": 0.38, "reached_via": ["FAM:SF-APPM-022 auto_related_family (record_link_related_to) FAM:SF-APPM-052"], "attributes": {"observed_research_question": "MIA vs BOS G6 2023 agent adaptation review", "auto_outcome_status": "inconclusive", "observed_hypothesis": "MIA failed to pivot after H1-H2 suppression of PULL_UP/PNR in 2023 ECF G6 (0042200306), leaving points vs H2H baseline.", "observed_result": "Agent review: H1 PPP 1.158 -> H2 0.971. PULL_UP 1.6 (n=5) -> 0.5 (n=6); cost vs H2H 1.361: (1.361-0.5)*6=5.166 points. PNR 1.0 (n=4) -> 0.333 (n=6); cost (1.0-0.333)*6=4.002. Combined 9.168 points. Tactical review: repor [cut; read_family for the full text]", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "n=1 game; two reviews disagree on the primary miss (PULL_UP vs PNR) and on whether overall H2 PPP fell (0.971 vs 1.171) because possession classification differs."}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:DRIFT_NONSTATIONARITY"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}, {"rel": "auto_related_family", "node": "FAM:SF-APPM-022"}]}, {"id": "FAM:SF05", "label": "Study family SF05: Coaching pickup: H1->H2 share shift toward BEST vs AVOID", "score": 0.378, "reached_via": ["FAM:SF-APPS-030 auto_related_family (record_link_related_to) FAM:SF05"], "attributes": {"observed_research_question": "Coaching pickup: H1->H2 share shift toward BEST vs AVOID", "auto_outcome_status": "rejected", "observed_hypothesis": "After suppression, teams shift volume toward the sheet BEST counter and away from AVOID.", "observed_result": "% shifted more toward BEST 51.6%; % used more AVOID 22.4%. Avg best pickup +0.0024 pp; BEST share 10.0%->10.2%. PO AVOID share within AVOID+INSUFF 13.4%->13.7% (+0.3 pp); BEST 12.9%->12.8%. RS AVOID +1.1 pp; BEST 13.1%-> [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "BEST pickup +0.24 pp is essentially zero; teams do not shift toward BEST; AVOID ticks up slightly.", "observed_sample_and_power": "n=591 triggers with BEST defined", "auto_validation_status": "same_pipeline_validation; evidence: repeat runs of the design agree", "observed_verdict": "null", "auto_confidence": "high (0.95)"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF08"}]}, {"id": "FAM:SF08", "label": "Study family SF08: Season adapter profiles (BEST-share consistency across seasons)", "score": 0.378, "reached_via": ["FAM:SF-APPS-030 auto_related_family (record_link_extends) FAM:SF08"], "attributes": {"observed_research_question": "Season adapter profiles (BEST-share consistency across seasons)", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Teams' post-trigger BEST vs AVOID mix is a stable coaching signature across seasons.", "observed_result": "Top mean BEST share: BOS 15.7% (10 dirs, win 70%), LAL 15.5%, GSW 13.8%. Bottom: HOU 2.5%, MIL 3.5%, LAC 4.1%. DEN 4.9% BEST / 70.8% INSUFF yet 62% win. ORL AVOID share 59.3%, 0% win.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No inferential test of stability vs noise; win% not identified with BEST share (IND 4.5% BEST, 71% win).", "observed_sample_and_power": "19 teams with n>=2 seasons", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "descriptive", "observed_failure_type": "E_unclear"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPS-027"}, {"rel": "auto_related_family", "node": "FAM:SF-APPS-030"}, {"rel": "auto_related_family", "node": "FAM:SF05"}]}], "n_results": 10}

